/// A and B at (roughness, mu), bilinear in the tables over (roughness,
/// sqrt(mu)); both clamped to [0, 1].
pub fn ggx_albedo_ab(roughness: f32, mu: f32) -> (f32, f32) {
    let n1 = (GGX_ALBEDO_N - 1) as f32;
    let x = roughness.clamp(0.0, 1.0) * n1;
    let y = mu.clamp(0.0, 1.0).sqrt() * n1;
    let i = (x as usize).min(GGX_ALBEDO_N - 2);
    let j = (y as usize).min(GGX_ALBEDO_N - 2);
    let (fx, fy) = (x - i as f32, y - j as f32);
    let (w00, w10, w01, w11) = ((1.0 - fx) * (1.0 - fy), fx * (1.0 - fy), (1.0 - fx) * fy, fx * fy);
    let a = w00 * GGX_ALBEDO_A[i][j] + w10 * GGX_ALBEDO_A[i + 1][j] + w01 * GGX_ALBEDO_A[i][j + 1]
        + w11 * GGX_ALBEDO_A[i + 1][j + 1];
    let b = w00 * GGX_ALBEDO_B[i][j] + w10 * GGX_ALBEDO_B[i + 1][j] + w01 * GGX_ALBEDO_B[i][j + 1]
        + w11 * GGX_ALBEDO_B[i + 1][j + 1];
    (a, b)
}

/// E_s(mu) of the lobe with reflectance f0 head on (one channel).
pub fn ggx_albedo(roughness: f32, mu: f32, f0: f32) -> f32 {
    let (a, b) = ggx_albedo_ab(roughness, mu);
    f0 * a + (1.0 - f0) * b
}

/// The cosine-weighted averages of A and B at this roughness, linear between
/// the rows, as the bilinear lookup's own average is.
pub fn ggx_albedo_average_ab(roughness: f32) -> (f32, f32) {
    let n1 = (GGX_ALBEDO_N - 1) as f32;
    let x = roughness.clamp(0.0, 1.0) * n1;
    let i = (x as usize).min(GGX_ALBEDO_N - 2);
    let fx = x - i as f32;
    ((1.0 - fx) * GGX_ALBEDO_A_AVG[i] + fx * GGX_ALBEDO_A_AVG[i + 1],
     (1.0 - fx) * GGX_ALBEDO_B_AVG[i] + fx * GGX_ALBEDO_B_AVG[i + 1])
}

/// Ebar_s, the average of E_s over the cosine-weighted hemisphere, for f0.
pub fn ggx_albedo_average(roughness: f32, f0: f32) -> f32 {
    let (a, b) = ggx_albedo_average_ab(roughness);
    f0 * a + (1.0 - f0) * b
}
